import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;

/**
 * Root view: keeps an in-memory list of items that can be added and cleared.
 */
@PageTitle("Items")
@Route(value = "", layout = MainLayout.class)
public class ItemsView extends VerticalLayout {

    private final List<String> items = new ArrayList<>();

    private final TextField itemField = new TextField("Item");
    private final UnorderedList itemList = new UnorderedList();
    private final Span itemCount = new Span();

    public ItemsView() {
        // The field is only invalid when an empty value was submitted, so keep
        // the client from validating (and thereby clearing) that state itself.
        itemField.setManualValidation(true);
        itemField.addValueChangeListener(event -> {
            if (!isBlank(event.getValue())) {
                itemField.setInvalid(false);
            }
        });

        Button addButton = new Button("Add", event -> addItem());
        Button clearButton = new Button("Clear", event -> clearItems());

        add(new H1("Items"), new HorizontalLayout(itemField, addButton, clearButton), itemList, itemCount);

        refresh();
    }

    private void addItem() {
        String value = itemField.getValue();
        if (isBlank(value)) {
            itemField.setInvalid(true);
            return;
        }
        items.add(value);
        itemField.setInvalid(false);
        itemField.clear();
        refresh();
    }

    private void clearItems() {
        items.clear();
        refresh();
    }

    private void refresh() {
        itemList.removeAll();
        items.forEach(item -> itemList.add(new ListItem(item)));
        itemCount.setText("Items: " + items.size());
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }

}
