class ItemsViewTest extends SpringBrowserlessTest {

    private TextField itemField;
    private Button addButton;
    private Button clearButton;

    @BeforeEach
    void openView() {
        navigate(ItemsView.class);
        itemField = $(TextField.class).withLabel("Item").single();
        addButton = $(Button.class).withText("Add").single();
        clearButton = $(Button.class).withText("Clear").single();
    }

    @Test
    void view_isRenderedInsideAppLayoutWithTitle() {
        assertThat($(AppLayout.class).exists()).isTrue();
        assertThat($(H2.class).withText("Item Tracker").exists()).isTrue();
        assertThat($(H1.class).withText("Items").exists()).isTrue();
    }

    @Test
    void initialState_isEmpty() {
        assertThat(itemField.getValue()).isEmpty();
        assertThat(addButton.isEnabled()).isTrue();
        assertThat(clearButton.isEnabled()).isTrue();
        assertThat(items()).isEmpty();
        assertThat(count()).isEqualTo("Items: 0");
    }

    @Test
    void add_appendsItemAndClearsField() {
        addItem("Milk");
        addItem("Bread");

        assertThat(items()).containsExactly("Milk", "Bread");
        assertThat(itemField.getValue()).isEmpty();
        assertThat(count()).isEqualTo("Items: 2");
        assertThat(itemField.isInvalid()).isFalse();
    }

    @Test
    void add_allowsDuplicates() {
        addItem("Milk");
        addItem("Milk");

        assertThat(items()).containsExactly("Milk", "Milk");
        assertThat(count()).isEqualTo("Items: 2");
    }

    @Test
    void add_withBlankValue_marksFieldInvalid() {
        test(itemField).setValue("   ");
        test(addButton).click();

        assertThat(items()).isEmpty();
        assertThat(count()).isEqualTo("Items: 0");
        assertThat(itemField.isInvalid()).isTrue();
    }

    @Test
    void add_withEmptyValue_marksFieldInvalid() {
        test(addButton).click();

        assertThat(items()).isEmpty();
        assertThat(count()).isEqualTo("Items: 0");
        assertThat(itemField.isInvalid()).isTrue();
    }

    @Test
    void clear_removesEveryItemAndAllowsAddingAgain() {
        addItem("Milk");
        addItem("Bread");

        test(clearButton).click();

        assertThat($(UnorderedList.class).single().getChildren()).isEmpty();
        assertThat(count()).isEqualTo("Items: 0");

        addItem("Eggs");
        assertThat(items()).containsExactly("Eggs");
        assertThat(count()).isEqualTo("Items: 1");
    }

    private void addItem(String value) {
        test(itemField).setValue(value);
        test(addButton).click();
    }

    private List<String> items() {
        return $(ListItem.class).all().stream().map(ListItem::getText).toList();
    }

    private String count() {
        return $(Span.class).withTextContaining("Items:").single().getText();
    }

}
